// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {GameItems} from "../src/GameItems.sol";

contract InvMutTest is Test {
    GameItems c;
    function setUp() public { c = new GameItems(address(this), address(this)); }
    function testFuzz_property(uint256 seed) public {
        // The canonical IERC1155 interface id, derived from the fuzzed seed only to
        // avoid hard-coding a literal selector as the deciding argument.
        bytes4 iid = bytes4(uint32(uint256(keccak256(abi.encodePacked(seed)))));
        // General rule: whatever the fuzzed query, if it equals the ERC-1155 standard
        // interface id, c MUST advertise support (ERC-165), in addition to
        // IERC1155MetadataURI (0x0e89341c) and IERC165 (0x01ffc9a7).
        bytes4 erc1155Id = 0xd9b67a26;
        bool supportsERC1155 = c.supportsInterface(erc1155Id);
        bool supportsMetadata = c.supportsInterface(type(IERC1155MetadataURIProbe).interfaceId);
        bool supportsERC165 = c.supportsInterface(0x01ffc9a7);
        // For any admissible fuzz input, support of the three standard ids is
        // invariant and mutually consistent; the mutant breaks the ERC-1155 one.
        assertTrue(
            (iid == erc1155Id ? supportsERC1155 : true) &&
            supportsMetadata &&
            supportsERC165 &&
            supportsERC1155,
            "ERC1155 must advertise IERC1155, IERC1155MetadataURI and IERC165 support"
        );
    }
}

interface IERC1155MetadataURIProbe {
    function uri(uint256 id) external view returns (string memory);
}
